// Catches render/chunk-load failures in a lazily loaded Product so one broken chunk
// (e.g. a deploy while the tab was open) degrades to a reload prompt, not a white screen.
class ScreenErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { hasError: false }; }
  static getDerivedStateFromError() { return { hasError: true }; }
  componentDidCatch(error, info) { console.error("screen render failed", error, info); }
  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center gap-3 py-24 text-center">
          <div className="text-sm font-bold" style={{ color: "#15262F" }}>画面の読み込みに失敗しました</div>
          <div className="text-xs" style={{ color: "#8593A0" }}>通信状況をご確認のうえ、再読み込みしてください。</div>
          <Btn size="sm" onClick={() => window.location.reload()}>再読み込み</Btn>
        </div>
      );
    }
    return this.props.children;
  }
}

