/* ===== UI プリミティブ ===== */
function Ring({ value, size = 96, stroke = 9, color = T.accent, track = T.border, children }) {
  const r = (size - stroke) / 2, c = 2 * Math.PI * r, off = c * (1 - value / 100);
  return <div className="relative" style={{ width: size, height: size }}>
    <svg width={size} height={size} className="-rotate-90">
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={track} strokeWidth={stroke} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round"
        strokeDasharray={c} strokeDashoffset={off} style={{ transition: "stroke-dashoffset 1s ease" }} /></svg>
    <div className="absolute inset-0 flex flex-col items-center justify-center">{children}</div></div>;
}
function Bar({ value, tone = "cyan" }) {
  const t = { cyan: T.accent, green: T.success, amber: T.warning };
  return <div className="h-2 w-full overflow-hidden rounded-full" style={{ background: T.border }}>
    <div className="h-full rounded-full" style={{ width: `${value}%`, background: t[tone], transition: "width .8s ease" }} /></div>;
}
function EmptyState({ img = "empty", title, desc }) {
  return <CommonEmptyState imageSrc={ILLUS[img]} title={title} desc={desc} />;
}
function useAIDraft() {
  const [busy, setBusy] = useState(false);
  function draft(cb, payload) { setBusy(true); setTimeout(() => { cb(payload); setBusy(false); }, 1100); }
  return { busy, draft };
}
function safeGoals(goals) {
  return Array.isArray(goals)
    ? goals.map(g => ({ ...g, tasks: Array.isArray(g?.tasks) ? g.tasks : [] }))
    : [];
}
function goalProgress(goals, done) {
  return safeGoals(goals).map(g => {
    const n = g.tasks.filter(t => done?.[t.id]).length;
    return { ...g, n, total: g.tasks.length, pct: g.tasks.length ? Math.round((n / g.tasks.length) * 100) : 0 };
  });
}
function flatTasks(goals) { return safeGoals(goals).flatMap(g => g.tasks.map(t => ({ ...t, goal: g.title, gid: g.id }))); }
function overallProgress(goals, done) {
  const all = flatTasks(goals); const n = all.filter(t => done?.[t.id]).length;
  return all.length ? Math.round((n / all.length) * 100) : 0;
}

